+  {
+    return;
+  }
+
+  if(cf->cache.states != NULL)
+  {
+    g_hash_table_destroy(cf->cache.states);
+    cf->cache.states = NULL;
+  }
+
+  cf->cache.max_state_count = 0;
+  cf->cache.is_valid = FALSE;
+  cf->cache.removal_policy = CFC_REMOVE_OLDEST;
